    nums = sorted(l)
    n = len(nums)

    # Iterate over each element, treating it as the first element of the triple
    for i in range(n - 2):
        # Two-pointer search for remaining two elements
        left, right = i + 1, n - 1
        while left < right:
            total = nums[i] + nums[left] + nums[right]
            if total == 0:
                return True
            elif total < 0:
                left += 1
            else:
